// Writes truth-map-config.js (read by truth-map-world.html) from the
// DASHBOARD_* variables in .env. The dashboard is a static page and can't
// read .env itself.
//
//   npm run dashboard:config
//
// The generated file contains the API key and is git-ignored.
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
require('dotenv').config({ path: path.join(root, '.env') });

const env = (name, fallback = '') => (process.env[name] ?? fallback).trim();

const config = {
  apiBase: env('DASHBOARD_API_BASE'),
  apiKey: env('DASHBOARD_API_KEY'),
  apiKeyHeader: env('DASHBOARD_API_KEY_HEADER', 'api-key'),
  apiKeyPrefix: env('DASHBOARD_API_KEY_PREFIX'),
  dataMode: env('DASHBOARD_DATA_MODE', 'live'),
  defaultCourse: env('DASHBOARD_DEFAULT_COURSE', 'OIAI AI Literacy Skills'),
  // Items hidden for everyone (set from the dashboard's Admin mode → "Save for everyone")
  hidden: env('DASHBOARD_HIDDEN').split(',').map(s => s.trim()).filter(Boolean),
  // PIN for Admin mode. Deters casual users only: it is readable in the generated file.
  adminPin: env('DASHBOARD_ADMIN_PIN'),
};
// Endpoints served by a different server than apiBase (empty = use apiBase)
const assessmentBase = env('DASHBOARD_ASSESSMENT_API_BASE');
if (assessmentBase) config.endpointBases = { assignmentScores: assessmentBase };

if (!config.apiBase) console.warn('⚠ DASHBOARD_API_BASE is empty in .env, so the dashboard has no data source.');
if (!config.apiKey) console.log('ℹ DASHBOARD_API_KEY is empty: fine when DASHBOARD_API_BASE is the proxy (proxy/README.md), otherwise requests get HTTP 401.');
if (!['auto', 'live', 'sample'].includes(config.dataMode)) {
  console.error(`✗ DASHBOARD_DATA_MODE must be auto, live or sample (got "${config.dataMode}")`);
  process.exit(1);
}

const out = `// GENERATED by scripts/generate-dashboard-config.js from .env. Do not edit or commit.
// Change the DASHBOARD_* values in .env, then run: npm run dashboard:config
//
// Anyone who can open the dashboard can read this key (browser devtools).
// For a public deployment, put the key in a server-side proxy instead.
window.TRUTH_MAP_CONFIG = ${JSON.stringify(config, null, 2)};
`;

const file = path.join(root, 'truth-map-config.js');
fs.writeFileSync(file, out);
console.log(`✓ Wrote ${path.relative(root, file)}: ${config.apiBase} · key ${config.apiKey ? 'set' : 'MISSING'} (header ${config.apiKeyHeader}) · mode ${config.dataMode} · default course "${config.defaultCourse}" · ${config.hidden.length} hidden item(s) · admin ${config.adminPin ? 'PIN set' : 'DISABLED (no DASHBOARD_ADMIN_PIN)'} · assessment from ${assessmentBase || 'apiBase'}`);
